#!/usr/bin/ruby
# frozen_string_literal: true

# Generates src/mica/encoding/tables/*.cr from the Encoding Standard's label
# list (encodings.json) and index files, at the commit pinned in
# conformance/encoding/fetch_vectors.rb.
#
#   /usr/bin/ruby conformance/encoding/fetch_vectors.rb
#   /usr/bin/ruby scripts/generate_encoding_tables.rb
#
# Every input file's sha256 is checked against conformance/encoding/MANIFEST
# before it is read; a mismatch stops the script and names the file. Each
# generated file starts with the commit and the sha256 of the files it came
# from. Tables are `Slice.literal`s, which compile to read-only data.
#
# Only the Ruby standard library is used (system /usr/bin/ruby).

require 'digest'
require 'fileutils'
require 'json'

ROOT = File.expand_path('..', __dir__)
VECTORS = File.join(ROOT, 'conformance/encoding-vectors/whatwg')
OUTPUT = File.join(ROOT, 'src/mica/encoding/tables')
WHATWG_COMMIT = File.read(File.join(ROOT, 'conformance/encoding/fetch_vectors.rb'))[/WHATWG_COMMIT = '(\h+)'/, 1]

MANIFEST = File.readlines(File.join(ROOT, 'conformance/encoding/MANIFEST'), chomp: true)
                .reject { |line| line.empty? || line.start_with?('#') }
                .map(&:split)
                .select { |source, _, _| source == 'whatwg' }
                .to_h { |_, path, sha256| [path, sha256] }

# The Encoding Standard's names and the `Mica::Encoding::Codec` members.
CODEC_FOR_NAME = {
  'UTF-8' => 'UTF8', 'IBM866' => 'IBM866',
  'ISO-8859-2' => 'ISO8859_2', 'ISO-8859-3' => 'ISO8859_3', 'ISO-8859-4' => 'ISO8859_4',
  'ISO-8859-5' => 'ISO8859_5', 'ISO-8859-6' => 'ISO8859_6', 'ISO-8859-7' => 'ISO8859_7',
  'ISO-8859-8' => 'ISO8859_8', 'ISO-8859-8-I' => 'ISO8859_8_I', 'ISO-8859-10' => 'ISO8859_10',
  'ISO-8859-13' => 'ISO8859_13', 'ISO-8859-14' => 'ISO8859_14', 'ISO-8859-15' => 'ISO8859_15',
  'ISO-8859-16' => 'ISO8859_16', 'KOI8-R' => 'KOI8_R', 'KOI8-U' => 'KOI8_U',
  'macintosh' => 'Macintosh', 'windows-874' => 'Windows874',
  'windows-1250' => 'Windows1250', 'windows-1251' => 'Windows1251', 'windows-1252' => 'Windows1252',
  'windows-1253' => 'Windows1253', 'windows-1254' => 'Windows1254', 'windows-1255' => 'Windows1255',
  'windows-1256' => 'Windows1256', 'windows-1257' => 'Windows1257', 'windows-1258' => 'Windows1258',
  'x-mac-cyrillic' => 'XMacCyrillic', 'GBK' => 'GBK', 'gb18030' => 'GB18030', 'Big5' => 'Big5',
  'EUC-JP' => 'EUCJP', 'ISO-2022-JP' => 'ISO2022JP', 'Shift_JIS' => 'ShiftJIS', 'EUC-KR' => 'EUCKR',
  'replacement' => 'Replacement', 'UTF-16BE' => 'UTF16BE', 'UTF-16LE' => 'UTF16LE',
  'x-user-defined' => 'XUserDefined'
}.freeze

def verified(path)
  expected = MANIFEST.fetch(path) { abort "#{path} is not in conformance/encoding/MANIFEST" }
  full = File.join(VECTORS, path)
  abort "#{full} is missing; run /usr/bin/ruby conformance/encoding/fetch_vectors.rb" unless File.exist?(full)
  actual = Digest::SHA256.file(full).hexdigest
  abort "sha256 mismatch for #{path}: expected #{expected}, got #{actual}" unless actual == expected
  File.read(full)
end

# Returns [[pointer, code_point], ...] in file order.
def read_index(name)
  verified("index-#{name}.txt").lines.map do |line|
    next if line.strip.empty? || line.start_with?('#')

    pointer, code_point = line.split("\t")
    [Integer(pointer.strip, 10), Integer(code_point.strip, 16)]
  end.compact
end

def header(io, files, purpose)
  io << "# GENERATED by scripts/generate_encoding_tables.rb; do not edit.\n"
  io << "# #{purpose}\n"
  io << "#\n# Source: https://github.com/whatwg/encoding at #{WHATWG_COMMIT}\n"
  files.each { |file| io << "#   #{file} sha256 #{MANIFEST.fetch(file)}\n" }
  io << "\n"
end

def literal(type, values, per_line = 16)
  return "Slice(#{type}).empty" if values.empty?

  lines = values.each_slice(per_line).map { |slice| '    ' + slice.join(', ') }
  "Slice(#{type}).literal(\n#{lines.join(",\n")}\n  )"
end

def build
  io = +""
  yield io
  io
end

def write(name, content)
  File.write(File.join(OUTPUT, name), content)
  puts "wrote src/mica/encoding/tables/#{name}"
end

# A reverse table for the Basic Multilingual Plane: `pages` holds, for each
# high byte, 0 or the 1-based number of a 256-entry block in `values`; each
# entry is the value plus one (0 = unmapped). Code points above U+FFFF go in
# a sorted pair list.
def reverse_tables(pairs)
  bmp = {}
  astral = {}
  pairs.each do |code_point, value|
    target = code_point > 0xFFFF ? astral : bmp
    target[code_point] = value unless target.key?(code_point)
  end
  pages = Array.new(256, 0)
  values = []
  bmp.keys.map { |cp| cp >> 8 }.uniq.sort.each_with_index do |page, number|
    pages[page] = number + 1
    block = Array.new(256, 0)
    bmp.each { |cp, value| block[cp & 0xFF] = value + 1 if cp >> 8 == page }
    values.concat(block)
  end
  sorted = astral.sort
  [pages, values, sorted.map(&:first), sorted.map(&:last)]
end

def emit_reverse(io, prefix, pairs, value_type)
  pages, values, astral_code_points, astral_values = reverse_tables(pairs)
  io << "  # Reverse lookup (code point -> #{prefix.downcase.tr('_', ' ')}): see Mica::Encoding::Tables.reverse.\n"
  io << "  #{prefix}_PAGES = #{literal('UInt16', pages)}\n\n"
  io << "  #{prefix}_VALUES = #{literal(value_type, values)}\n\n"
  io << "  #{prefix}_ASTRAL_CODE_POINTS = #{literal('UInt32', astral_code_points)}\n\n"
  io << "  #{prefix}_ASTRAL_VALUES = #{literal(value_type, astral_values)}\n\n"
end

FileUtils.mkdir_p(OUTPUT)

# --- Labels ---------------------------------------------------------------
groups = JSON.parse(verified('encodings.json'))
label_lines = []
groups.each do |group|
  group['encodings'].each do |encoding|
    codec = CODEC_FOR_NAME.fetch(encoding['name']) { abort "no codec for #{encoding['name']}" }
    encoding['labels'].each { |label| label_lines << "    #{label.inspect} => Codec::#{codec}," }
  end
end
write('labels.cr', build do |io|
  header(io, ['encodings.json'], 'Every label of the Encoding Standard and its encoding.')
  io << "module Mica::Encoding::Tables\n"
  io << "  # #{label_lines.size} labels, already trimmed and ASCII-lowercased.\n"
  io << "  WEB_LABELS = {\n#{label_lines.join("\n")}\n  }\n"
  io << "end\n"
end)

# --- Single-byte encodings ------------------------------------------------
single_byte = groups.find { |group| group['heading'] == 'Legacy single-byte encodings' }['encodings'].map { |encoding| encoding['name'] }
single_byte_files = single_byte.reject { |name| name == 'ISO-8859-8-I' }.map { |name| "index-#{name.downcase}.txt" }
write('single_byte.cr', build do |io|
  header(io, single_byte_files, 'Index single-byte for each legacy single-byte encoding.')
  io << "module Mica::Encoding::Tables\n"
  single_byte.each do |name|
    next if name == 'ISO-8859-8-I' # shares ISO-8859-8's index

    constant = CODEC_FOR_NAME.fetch(name).upcase
    forward = Array.new(128, 0)
    index = read_index(name.downcase)
    index.each do |pointer, code_point|
      abort "#{name}: pointer #{pointer} out of range" unless pointer.between?(0, 127)
      abort "#{name}: code point #{code_point} cannot be stored" unless code_point.between?(1, 0xFFFF)
      forward[pointer] = code_point
    end
    io << "  # #{name}: bytes 0x80 to 0xFF; 0 means no code point.\n"
    io << "  #{constant} = #{literal('UInt16', forward)}\n\n"
    emit_reverse(io, "#{constant}_ENCODE", index.map { |pointer, cp| [cp, pointer] }, 'UInt8')
  end
  io << "end\n"
end)

# --- Multi-byte indexes ---------------------------------------------------
def forward_table(index, name)
  size = index.map(&:first).max + 1
  table = Array.new(size, 0)
  index.each do |pointer, code_point|
    abort "#{name}: code point 0 cannot be stored" if code_point.zero?
    table[pointer] = code_point
  end
  table
end

jis0208 = read_index('jis0208')
write('jis0208.cr', build do |io|
  header(io, ['index-jis0208.txt'], 'Index jis0208 (EUC-JP, ISO-2022-JP and Shift_JIS).')
  io << "module Mica::Encoding::Tables\n"
  io << "  JIS0208 = #{literal('UInt16', forward_table(jis0208, 'jis0208'))}\n\n"
  # Index pointer: the first pointer for a code point.
  emit_reverse(io, 'JIS0208_ENCODE', jis0208.map { |pointer, cp| [cp, pointer] }, 'UInt16')
  # Index Shift_JIS pointer: the first pointer outside 8272 to 8835.
  emit_reverse(io, 'SHIFT_JIS_ENCODE', jis0208.reject { |pointer, _| pointer.between?(8272, 8835) }.map { |pointer, cp| [cp, pointer] }, 'UInt16')
  io << "end\n"
end)

jis0212 = read_index('jis0212')
write('jis0212.cr', build do |io|
  header(io, ['index-jis0212.txt'], 'Index jis0212 (EUC-JP decoder only).')
  io << "module Mica::Encoding::Tables\n"
  io << "  JIS0212 = #{literal('UInt16', forward_table(jis0212, 'jis0212'))}\n"
  io << "end\n"
end)

katakana = read_index('iso-2022-jp-katakana')
write('iso_2022_jp_katakana.cr', build do |io|
  header(io, ['index-iso-2022-jp-katakana.txt'], 'Index ISO-2022-JP katakana (U+FF61 to U+FF9F to fullwidth).')
  io << "module Mica::Encoding::Tables\n"
  io << "  ISO_2022_JP_KATAKANA = #{literal('UInt16', forward_table(katakana, 'katakana'))}\n"
  io << "end\n"
end)

euc_kr = read_index('euc-kr')
write('euc_kr.cr', build do |io|
  header(io, ['index-euc-kr.txt'], 'Index EUC-KR.')
  io << "module Mica::Encoding::Tables\n"
  io << "  EUC_KR = #{literal('UInt16', forward_table(euc_kr, 'euc-kr'))}\n\n"
  emit_reverse(io, 'EUC_KR_ENCODE', euc_kr.map { |pointer, cp| [cp, pointer] }, 'UInt16')
  io << "end\n"
end)

gb18030 = read_index('gb18030')
ranges = read_index('gb18030-ranges')
write('gb18030.cr', build do |io|
  header(io, ['index-gb18030.txt', 'index-gb18030-ranges.txt'], 'Index gb18030 and index gb18030 ranges.')
  io << "module Mica::Encoding::Tables\n"
  io << "  GB18030 = #{literal('UInt16', forward_table(gb18030, 'gb18030'))}\n\n"
  emit_reverse(io, 'GB18030_ENCODE', gb18030.map { |pointer, cp| [cp, pointer] }, 'UInt16')
  io << "  # Index gb18030 ranges: pointer offsets and their code point offsets, both ascending.\n"
  io << "  GB18030_RANGE_POINTERS = #{literal('UInt32', ranges.map(&:first))}\n\n"
  io << "  GB18030_RANGE_CODE_POINTS = #{literal('UInt32', ranges.map(&:last))}\n"
  io << "end\n"
end)

big5 = read_index('big5')
big5_last = [0x2550, 0x255E, 0x2561, 0x256A, 0x5341, 0x5345]
# Index Big5 pointer: pointers below (0xA1 - 0x81) * 157 excluded, and the last
# pointer for the six code points above.
standard = big5.reject { |pointer, _| pointer < (0xA1 - 0x81) * 157 }
big5_pairs = standard.map { |pointer, cp| [cp, pointer] }
big5_last.each do |cp|
  last = standard.select { |_, code_point| code_point == cp }.map(&:first).max
  big5_pairs.reject! { |code_point, _| code_point == cp }
  big5_pairs.unshift([cp, last])
end
# BIG5-HKSCS (iconv-compatible rule): the Big5 pointer where there is one,
# otherwise the first pointer anywhere in the index, so the Hong Kong
# Supplementary Character Set encodes too.
hkscs_pairs = big5_pairs + big5.map { |pointer, cp| [cp, pointer] }
write('big5.cr', build do |io|
  header(io, ['index-big5.txt'], 'Index Big5.')
  io << "module Mica::Encoding::Tables\n"
  io << "  BIG5 = #{literal('UInt32', forward_table(big5, 'big5'))}\n\n"
  emit_reverse(io, 'BIG5_ENCODE', big5_pairs, 'UInt16')
  emit_reverse(io, 'BIG5_HKSCS_ENCODE', hkscs_pairs, 'UInt16')
  io << "end\n"
end)
